const headers = $input.first().json.headers || {};
const lower = Object.fromEntries(Object.entries(headers).map(([k, v]) => [String(k).toLowerCase(), v]));
const token = String(lower['x-tradesejon-secret'] || lower['x-operator-token'] || lower['x-ceo-token'] || '');
const expected = String($env.WORKSHOP_LAUNCH_TOKEN || $env.TRADESAJON_BRIDGE_SECRET || '');
if (!expected || token !== expected) {
  return [{ json: { ok: false, authorized: false, httpStatus: 401, error: 'unauthorized' } }];
}
const body = $input.first().json.body || $input.first().json || {};
return [{ json: { ok: true, authorized: true, body } }];

const item = $input.first().json;
if (!item.authorized) return [{ json: item }];
const b = item.body || {};

const INVALID_DOMAINS = new Set([
  'gmai.com','gmial.com','gamil.com','gmail.con','gmail.cmo','gmail.comm','gmail.co','gmail.cm','gmail.om',
  'yaho.com','yahooo.com','yahoo.con','yahoo.comm','hotmial.com','hotmail.con','hotmail.comm',
  'outlok.com','outlook.con','outlook.comm','icloud.con','icloud.comm'
]);
const INVALID_TLDS = new Set(['comm','con','cmo','cor','vom','xom','cm','om']);
const EMAIL_RE = /^[A-Za-z0-9](?:[A-Za-z0-9._%+-]{0,62}[A-Za-z0-9])?@[A-Za-z0-9][A-Za-z0-9-]{0,61}[A-Za-z0-9](?:\.[A-Za-z0-9][A-Za-z0-9-]{0,61}[A-Za-z0-9])*\.[A-Za-z]{2,63}$/;

function forceFormatEmail(raw) {
  const cleaned = String(raw || '').replace(/^[\s\u200b-\u200f\u202a-\u202e\ufeff]+|[\s\u200b-\u200f\u202a-\u202e\ufeff]+$/g, '').toLowerCase();
  if (!cleaned || (cleaned.match(/@/g) || []).length !== 1 || cleaned.includes('..') || /\s/.test(cleaned) || !EMAIL_RE.test(cleaned)) return '';
  const domain = cleaned.split('@')[1];
  const tld = domain.split('.').pop();
  if (INVALID_DOMAINS.has(domain) || INVALID_TLDS.has(tld)) return '';
  return cleaned;
}

const email = forceFormatEmail(b.email || '');
const phoneRaw = String(b.phone || '').replace(/[\s\-()]/g, '');
const phoneOk = /^(?:\+?20|0)?1[0125]\d{8}$/.test(phoneRaw) || /^\+?[1-9]\d{7,14}$/.test(phoneRaw);
const dummy = new Set(['12345678','123456789','1234567890','0123456789','987654321']);
const digits = phoneRaw.replace(/\D/g, '');
const plausiblePhone = phoneOk && digits.length >= 8 && new Set(digits.slice(-8).split('')).size > 1 && !dummy.has(digits);

if (!email || !plausiblePhone) {
  return [{ json: { ok: false, valid: false, httpStatus: 400, error: !email ? 'invalid_email' : 'invalid_phone' } }];
}
const phoneE164 = digits.startsWith('01') ? '+20' + digits.slice(1) : (digits.startsWith('1') && digits.length === 10 ? '+20' + digits : '+' + digits);
const level = ['entry', 'intermediate', 'advanced'].includes(String(b.trading_level || '').toLowerCase()) ? String(b.trading_level).toLowerCase() : 'entry';
const country = String(b.country || 'مصر').trim();

return [{
  json: {
    ok: true,
    valid: true,
    discord_user_id: String(b.discord_user_id || ''),
    discord_username: String(b.discord_username || ''),
    full_name: String(b.full_name || email.split('@')[0]),
    email,
    phone_e164: phoneE164,
    country,
    trading_level: level,
    watched_videos: Boolean(b.watched_videos),
    free_otp_url: 'https://whop.com/checkout/plan_TEMPLATE_01',
    updated_at: new Date().toISOString()
  }
}];

const d = $input.first().json;
if (!d.valid) return [{ json: d }];
const { MongoClient } = require('mongodb');
const uri = $env.MONGODB_URI;
if (!uri) throw new Error('MONGODB_URI is not set');
const client = new MongoClient(uri);
await client.connect();
try {
  const db = client.db($env.MONGODB_DB || 'automation_hub');
  const doc = {
    discord_user_id: d.discord_user_id,
    discord_username: d.discord_username,
    full_name: d.full_name,
    email: d.email,
    phone: d.phone_e164,
    phoneE164: d.phone_e164,
    country: d.country,
    trading_level: d.trading_level,
    watched_videos: d.watched_videos,
    status: 'pending_whop_otp',
    whop_otp_verified: false,
    paid: false,
    updated_at: new Date()
  };
  await db.collection('trading_leads').updateOne({ email: d.email }, { $set: doc, $setOnInsert: { created_at: new Date() } }, { upsert: true });
  await db.collection('leads').updateOne({ email: d.email }, { $set: doc, $setOnInsert: { created_at: new Date() } }, { upsert: true });
  await db.collection('client_files').updateOne({ discord_user_id: d.discord_user_id || d.email }, { $set: doc, $setOnInsert: { created_at: new Date() } }, { upsert: true });
} finally {
  await client.close();
}
return [{ json: d }];
